function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith("sb_publishable_") || value.startsWith("sb_secret_");
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

function createSupabaseAdminClient() {
  const urlCandidate = process.env["SUPABASE_URL"] || process.env["VITE_SUPABASE_URL"] || "";
  const keyCandidate =
    process.env["SUPABASE_SERVICE_ROLE_KEY"] ||
    process.env["SUPABASE_PUBLISHABLE_KEY"] ||
    process.env["VITE_SUPABASE_PUBLISHABLE_KEY"] ||
    "";

  const SUPABASE_URL = urlCandidate.trim();
  const SUPABASE_SERVICE_ROLE_KEY = keyCandidate.trim();

  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ["SUPABASE_URL"] : []),
      ...(!SUPABASE_SERVICE_ROLE_KEY
        ? ["SUPABASE_SERVICE_ROLE_KEY / SUPABASE_PUBLISHABLE_KEY"]
        : []),
    ];
    console.warn(
      `[Supabase Admin] Missing environment variable(s): ${missing.join(", ")}. Configure credentials to enable server database access.`,
    );
  }

  if (!process.env["SUPABASE_SERVICE_ROLE_KEY"]?.trim()) {
    console.warn(
      "[Supabase] SUPABASE_SERVICE_ROLE_KEY is not set in environment. Falling back to publishable key for server requests.",
    );
  }

  const activeUrl = SUPABASE_URL || "https://placeholder.supabase.co";
  const activeKey = SUPABASE_SERVICE_ROLE_KEY || "placeholder-key";

  return createClient<Database>(activeUrl, activeKey, {
    global: {
      fetch: createSupabaseFetch(activeKey),
    },
    auth: {
      storage: undefined,
      persistSession: false,
      autoRefreshToken: false,
    },
  });
}

